import PersonalInfo from './PersonalInfo';
import MainHeading from '@/components/heading/MainHeading';

import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useMemo, useState } from 'react';
// import { AddDepartmentFormValues, AddDepartmentSchema } from '../schemas/addDepartment/add-department-schema';
import Submission from './Submission';
import { format } from 'date-fns';
import { Department } from '@/types/department.types';
import { AddDepartmentFormValues, AddDepartmentSchema } from '../schemas/addDepartment/add-department-schema';

interface Props {
    department?: Department | null;
}

export default function AddDepartmentForm({ department }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);

    const defaultValues = useMemo(
        () => ({
            name: department?.name || '',
            address: department?.address || '',
            id_number: department?.id_number || '',
            birth_date: department?.birth_date ? new Date(department.birth_date) : undefined,
            phone_number: department?.phone_number || '',
            email: department?.email || '',
            // personal_image: department?.personal_image || undefined,
            education_degree: department?.education_degree || '',
            university: department?.university || '',
            specialization: department?.specialization || '',
            graduation_year: department?.graduation_year || undefined,
            skills: department?.skills || undefined,
            previous_experience: department?.previous_experience || undefined,
            // degree_certificate: department?.degree_certificate || undefined,
            department_number: department?.department_number || '',
            department: department?.department || '',
            position: department?.position || '',
            branch_id: department?.branch_id ? String(department.branch_id) : '',
            shift_id: department?.shift_id ? String(department.shift_id) : '',
            contract_type: department?.contract_type || '',
            password: department?.password || '',
            // attachment: department?.attachment || undefined,
        }),
        [department],
    );

    const form = useForm<AddDepartmentFormValues>({
        resolver: zodResolver(AddDepartmentSchema),
        defaultValues,
    });

    const onSubmit = async (data: AddDepartmentFormValues) => {
        setLoading(true);
        setError(null); // Clear previous errors
        const formatedData = {
            ...data,
            birth_date: format(data.birth_date, 'yyyy-MM-dd'),
        };
        try {
            await apiPost({
                endpoint: department ? endpoints.departments.update + department.id : endpoints.departments.create,
                body: formatedData,
                config: { headers: { 'Content-Type': 'multipart/form-data' } },
            });
            setShowSuccessPopup(true);
        } catch (error: any) {
            if (error.response?.data?.errors) {
                // Handle field-specific errors
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                // Handle generic error
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response) {
                    errorMessage = error.response.data.msg || errorMessage;
                } else if (error.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mb-8">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div>
                        <MainHeading text="البيانات الشخصية" />
                        <PersonalInfo image={department?.personal_image} />

                    </div>
                    <Submission
                        department={department}
                        loading={loading}
                        setShowCancelPopup={setShowCancelPopup}
                        setShowSuccessPopup={setShowSuccessPopup}
                        showCancelPopup={showCancelPopup}
                        showSuccessPopup={showSuccessPopup}
                    />
                </form>
            </Form>
        </>
    );
}
