import SuccessPopup from '@/components/Popups/SuccessPopup';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import CancelPopup from '@/components/Popups/CancelPopup';
import { useNavigate } from 'react-router-dom';
import { Department } from '@/types/department.types';

interface Props {
    department?: Department | null;
    showSuccessPopup: boolean;
    setShowSuccessPopup: (value: boolean) => void;
    showCancelPopup: boolean;
    setShowCancelPopup: (value: boolean) => void;
    loading: boolean;
}
export default function Submission({
    department,
    setShowCancelPopup,
    setShowSuccessPopup,
    showCancelPopup,
    showSuccessPopup,
    loading,
}: Props) {
    const navigate = useNavigate();

    const handleAddAnother = () => {
        setShowSuccessPopup(false);
    };
    return (
        <>
            <div className="flex flex-row justify-end items-center mt-8">
                {department ? (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] xl:py-3 text-[#A21515] border border-red-error-50 xl:font-semibold bg-red-error-50"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        إلغاء إضافة القسم
                    </SecondaryButton>
                ) : (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] bg-red-error-50 text-[#A21515] hover:bg-red-error-600 hover:text-white-blue-50 xl:py-3 border bordr-[#E8EFF6] xl:font-semibold"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        الغاء
                    </SecondaryButton>
                )}
                <div>
                    {department ? (
                        <PrimaryButton className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'حفظ التغييرات'}
                        </PrimaryButton>
                    ) : (
                        <PrimaryButton className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'اضافة'}
                        </PrimaryButton>
                    )}
                </div>
            </div>
            <CancelPopup
                open={showCancelPopup}
                onClickButton1={() => {
                    setShowCancelPopup(false);
                }}
                onClickButton2={() => {
                    navigate('/human-resources/departments');
                    setShowCancelPopup(false);
                }}
                text1={department ? 'إلغاء تعديل بيانات القسم' : 'إلغاء إضافة قسم'}
                text2={
                    department
                        ? 'أنت على وشك إلغاء عملية تعديل بيانات القسم دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                        : 'أنت على وشك إلغاء عملية إضافة قسم جديد دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                }
                textButton1={department ? 'إكمال التعديل' : 'إكمال الإضافة'}
                textButton2={department ? 'إلغاء التعديل' : 'إلغاء الإضافة'}
            />
            <SuccessPopup
                text1={department ? 'تم تعديل بيانات القسم بنحاح' : 'تم إضافة قسم جديد بنحاح'}
                text2={department ? 'تم تعديل بيانات القسم بنحاح' : 'تم تسجيل بيانات القسم الجديد بنجاح.'}
                textButton1="العودة لقائمة الاقسام"
                textButton2={department ? 'تعديل بيانات اخرى' : 'إضافة قسم أخر'}
                open={showSuccessPopup}
                onAddAnother={handleAddAnother}
                onReturnToList={() => {
                    navigate('/human-resources/departments');
                    setShowSuccessPopup(false);
                }}
            />
        </>
    );
}
